{"explanation":"An inscribed angle is half the measure of the arc it intercepts—the arc between the two fixed endpoints that does not contain the moving point. Drag the yellow point around the circle: the angle stays at 50° while you remain on the same arc. Crossing an endpoint switches it to the supplementary angle, 130°; at the endpoints themselves, the angle is undefined.","manimCode":"const center = [-2, -0.15, 0];
const radius = 2.25;
const radians = degrees => degrees * Math.PI / 180;
const circlePoint = angle => [center[0] + radius * Math.cos(angle), center[1] + radius * Math.sin(angle), 0];
const aAngle = radians(220);
const bAngle = radians(320);
const pointA = circlePoint(aAngle);
const pointB = circlePoint(bAngle);

const title = new Text({ text: 'The inscribed angle theorem', fontSize: 30, color: WHITE });
title.moveTo([0, 3.25, 0]);
const circle = new Circle({ radius, color: BLUE });
circle.moveTo(center);
const chord = new Line({ start: pointA, end: pointB, color: BLUE });
const centralRays = new VGroup(
  new Line({ start: center, end: pointA, color: GRAY }),
  new Line({ start: center, end: pointB, color: GRAY })
);
const centerDot = new Dot({ point: center, color: GRAY });
const centralArcPoints = [];
for (let i = 0; i <= 40; i++) {
  const angle = aAngle + (bAngle - aAngle) * i / 40;
  centralArcPoints.push([center[0] + 0.62 * Math.cos(angle), center[1] + 0.62 * Math.sin(angle), 0]);
}
const centralArc = new Polygon({ vertices: centralArcPoints, color: ORANGE });
centralArc.setFillOpacity(0);
centralArc.setStrokeWidth(3);
const centralLabel = new Text({ text: '100°', fontSize: 22, color: ORANGE });
centralLabel.moveTo([center[0], center[1] - 0.95, 0]);

const endpointA = new Dot({ point: pointA, color: BLUE });
const endpointB = new Dot({ point: pointB, color: BLUE });
const labelA = new Text({ text: 'A', fontSize: 23, color: BLUE });
labelA.moveTo([pointA[0] - 0.25, pointA[1] - 0.27, 0]);
const labelB = new Text({ text: 'B', fontSize: 23, color: BLUE });
labelB.moveTo([pointB[0] + 0.25, pointB[1] - 0.27, 0]);

const movingPoint = new Dot({ point: circlePoint(Math.PI / 2), color: YELLOW });
const rays = new Polygon({ vertices: [pointA, movingPoint.getCenter(), pointB], color: YELLOW });
rays.setFillOpacity(0);
rays.setStrokeWidth(3);
const angleArc = new Polygon({ vertices: [[0, 0, 0], [0.1, 0, 0]], color: YELLOW });
angleArc.setFillOpacity(0);
angleArc.setStrokeWidth(4);
let angleReadout = null;
let arcReadout = null;
let statusReadout = null;

const sideHeading = new Text({ text: 'Drag the yellow point', fontSize: 25, color: YELLOW });
sideHeading.moveTo([3.05, 1.9, 0]);
const fixedNote = new Text({ text: 'A and B stay fixed', fontSize: 21, color: BLUE });
fixedNote.moveTo([3.05, 1.35, 0]);
const footnote = new Text({ text: 'Same arc → same inscribed angle', fontSize: 24, color: WHITE });
footnote.moveTo([0, -3.15, 0]);

function replaceReadout(oldLabel, value, y, color, fontSize) {
  if (oldLabel) scene.remove(oldLabel);
  const freshLabel = new Text({ text: value, fontSize, color });
  freshLabel.moveTo([3.05, y, 0]);
  scene.add(freshLabel);
  return freshLabel;
}

function refreshGeometry() {
  const p = movingPoint.getCenter();
  rays.setVertices([pointA, p, pointB]);
  const ux = pointA[0] - p[0];
  const uy = pointA[1] - p[1];
  const vx = pointB[0] - p[0];
  const vy = pointB[1] - p[1];
  const lenA = Math.hypot(ux, uy);
  const lenB = Math.hypot(vx, vy);
  if (Math.min(lenA, lenB) < 0.025) {
    angleArc.setOpacity(0);
    angleReadout = replaceReadout(angleReadout, 'Angle undefined', 0.4, YELLOW, 28);
    arcReadout = replaceReadout(arcReadout, 'Two vertices coincide', -0.35, WHITE, 21);
    statusReadout = replaceReadout(statusReadout, 'Move away from A or B', -1.15, GRAY, 19);
    return;
  }
  angleArc.setOpacity(1);
  const startAngle = Math.atan2(uy, ux);
  let sweep = Math.atan2(vy, vx) - startAngle;
  while (sweep > Math.PI) sweep -= 2 * Math.PI;
  while (sweep < -Math.PI) sweep += 2 * Math.PI;
  const arcVertices = [];
  const arcRadius = Math.min(0.43, lenA * 0.35, lenB * 0.35);
  for (let i = 0; i <= 30; i++) {
    const theta = startAngle + sweep * i / 30;
    arcVertices.push([p[0] + arcRadius * Math.cos(theta), p[1] + arcRadius * Math.sin(theta), 0]);
  }
  angleArc.setVertices(arcVertices);
  const degrees = Math.abs(sweep) * 180 / Math.PI;
  const isSmall = degrees < 90;
  angleReadout = replaceReadout(angleReadout, 'Angle APB = ' + Math.round(degrees) + '°', 0.4, YELLOW, 28);
  arcReadout = replaceReadout(arcReadout, isSmall ? '½ × 100° = 50°' : '½ × 260° = 130°', -0.35, WHITE, 25);
  statusReadout = replaceReadout(statusReadout, isSmall ? 'Intercepts the lower arc' : 'Intercepts the upper arc', -1.15, GRAY, 19);
}

await scene.play(new Write(title));
await scene.play(new Create(circle));
scene.add(chord, centralRays, centerDot, centralArc, centralLabel, endpointA, endpointB, labelA, labelB);
scene.add(rays, angleArc, movingPoint, sideHeading, fixedNote, footnote);
refreshGeometry();
makeDraggable(movingPoint, scene, {
  constrainX: [center[0] - radius, center[0] + radius],
  constrainY: [center[1] - radius, center[1] + radius],
  onDrag: (mob, pos) => {
    const dx = pos[0] - center[0];
    const dy = pos[1] - center[1];
    if (Math.hypot(dx, dy) < 0.001) return;
    mob.moveTo(circlePoint(Math.atan2(dy, dx)));
    refreshGeometry();
  }
});
await scene.wait(999999);"}

